from functools import total_ordering


@total_ordering
class Money:
    def __init__(self, cents, currency):
        self.cents = cents
        self.currency = currency

    def __repr__(self):
        return f"Money({self.cents}, {repr(self.currency)})"

    def __str__(self):
        sign = "-" if self.cents < 0 else ""
        whole, rest = divmod(abs(self.cents), 100)
        return f"{sign}{whole}.{rest:02} {self.currency}"

    def _same(self, other):
        if self.currency != other.currency:
            raise ValueError(f"cannot mix {self.currency} and {other.currency}")

    def __add__(self, other):
        self._same(other)
        return Money(self.cents + other.cents, self.currency)

    def __mul__(self, factor):
        return Money(self.cents * factor, self.currency)

    def __rmul__(self, factor):
        return self * factor

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return (self.cents, self.currency) == (other.cents, other.currency)

    def __lt__(self, other):
        self._same(other)
        return self.cents < other.cents

    def __hash__(self):
        return hash((self.cents, self.currency))

unitTests:
@test("printing")
def _():
    check_eq(repr(Money(1250, "EUR")), "Money(1250, 'EUR')")
    check_eq(str(Money(1250, "EUR")), "12.50 EUR")
    check_eq(str(Money(7, "USD")), "0.07 USD")
    check_eq(f"{Money(-5, 'USD')}", "-0.05 USD")

@test("arithmetic")
def _():
    m = Money(1250, "EUR")
    check_eq(m + Money(5, "EUR"), Money(1255, "EUR"))
    check_eq(m * 3, Money(3750, "EUR"))
    check_eq(3 * m, Money(3750, "EUR"))
    check_eq(sum([Money(1, "EUR"), Money(2, "EUR")], Money(0, "EUR")), Money(3, "EUR"))
    check_raises(ValueError, lambda: m + Money(1, "USD"))

@test("comparing")
def _():
    a, b = Money(100, "EUR"), Money(250, "EUR")
    check(a < b and b > a and a <= a and b >= a)
    check_eq(sorted([b, a]), [a, b])
    check(Money(1, "EUR") != Money(1, "USD"))
    check(Money(1, "EUR") != 1)
    check_raises(ValueError, lambda: a < Money(1, "USD"))

@test("hashing")
def _():
    check_eq(len({Money(1250, "EUR"), Money(1250, "EUR"), Money(1, "EUR")}), 2)
    prices = {Money(100, "EUR"): "cheap"}
    check_eq(prices[Money(100, "EUR")], "cheap")

